+        Record::Param { name: "SpindleSpeed".into(), value: serde_json::json!(900.0) },
+        Record::Param { name: "ClearancePlane".into(), value: serde_json::json!(10.0) },
+        Record::Param { name: "RetractPlane".into(), value: serde_json::json!(10.0) },
