+    let out_inch = engine::run_with(&script, &machine, &cnc::serialize(&records), &opts_inch)
+        .expect("inch post engine");
+    assert!(
+        out_inch.program.contains("N10 G17 G700 G90 G94 G54 G40 G80"),
+        "840D inch preamble must state G94:\n{}",
